import { createElement } from 'react';

import { BarChart2, Table } from 'components/icon';

export const SEGMENTED_CONTROL_OPTIONS = [
  {
    value: 'chart',
    image: createElement(BarChart2, { size: 'small', 'aria-hidden': true }),
  },
  {
    value: 'table',
    image: createElement(Table, { size: 'small', 'aria-hidden': true }),
  },
];
export const REFRESH_DATE_SKELETON_PROPS = {
  width: '200px',
  height: '24px',
  length: 1,
  borderRadius: 'small' as const,
};
